INSERT INTO `lessons` VALUES (1,1,1,1,'Mengenal Panca Indra Kita & Kebersihan Diri','mengenal-panca-indra-kita','Tubuh kita memiliki 5 indra hebat untuk melihat, mendengar, mencium, mengecap, dan meraba keindahan dunia!','[{\"text\": \"Hai sahabat kecil! Di tubuh kita ada 5 indra ajaib.\\nMata untuk melihat pelangi yang indah.\\nTelinga untuk mendengar kicau burung dan musik riang.\", \"title\": \"Apa itu Panca Indra?\", \"highlight\": \"Mata (Melihat) & Telinga (Mendengar)\"}, {\"text\": \"Hidung kita mencium aroma kue bolu mama yang harum.\\nLidah kita mengecap manisnya madu dan segarnya buah jeruk.\", \"title\": \"Hidung dan Lidah yang Hebat\", \"highlight\": \"Hidung (Membau) & Lidah (Mengecap Rasa)\"}, {\"text\": \"Kulit kita meraba halusnya bulu kelinci dan dinginnya es.\\nJangan lupa mandi 2 kali sehari dan cuci tangan sebelum makan!\", \"title\": \"Kulit Lembut & Merawat Kebersihan\", \"highlight\": \"Kulit (Meraba) & Rajin Cuci Tangan\"}]','https://images.unsplash.com/photo-1502086223501-7ea6ecd79368?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/g3yW7B0bZ_Y',7,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(2,1,1,2,'Membedakan Benda Hidup dan Benda Mati','benda-hidup-dan-benda-mati','Di sekitar kita ada benda hidup yang bisa tumbuh dan bernapas, serta benda mati yang tidak membutuhkan makanan.','[{\"text\": \"Kucing yang lincah, pohon mangga, dan adik bayi adalah makhluk hidup.\\nMereka bernapas, makan, minum, dan bisa bertambah besar!\", \"title\": \"Ciri Khas Makhluk Hidup\", \"highlight\": \"Makhluk hidup butuh makan dan bisa tumbuh\"}, {\"text\": \"Meja belajar, pensil warna, dan bola sepak adalah benda mati.\\nBenda mati tidak bisa bergerak sendiri dan tidak butuh makan.\", \"title\": \"Benda Mati di Rumah Kita\", \"highlight\": \"Benda mati tidak bernapas dan tidak tumbuh\"}]','https://images.unsplash.com/photo-1534567153574-2b12153a87f0?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/WbHj9fM_fO0',6,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(3,1,2,1,'Silsilah Keluarga & Peran Anggota Keluarga','silsilah-keluarga-dan-peran-anggota','Keluarga adalah rumah penuh cinta kasih. Mengenal peran ayah, ibu, kakak, dan adik yang saling tolong-menolong.','[{\"text\": \"Kakek dan nenek memiliki anak, yaitu ayah dan ibu kita.\\nAyah dan ibu melahirkan kita, kakak, dan adik tercinta.\", \"title\": \"Pohon Silsilah Keluarga\", \"highlight\": \"Kakek, Nenek, Orang Tua, dan Anak\"}, {\"text\": \"Ayah mencari nafkah, ibu mengasuh dan membimbing kita.\\nAnak-anak bertugas belajar rajin dan merapikan mainan sendiri.\", \"title\": \"Tugas & Kerjasama di Rumah\", \"highlight\": \"Saling menyayangi dan membantu pekerjaan rumah\"}]','https://images.unsplash.com/photo-1511895426328-dc8714191300?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/Fe8u2I3vmHU',8,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(4,1,3,1,'Siklus Daur Hidup Kupu-Kupu (Metamorfosis)','siklus-daur-hidup-kupu-kupu','Dari telur mungil di atas daun, ulat rakus pemakan daun, kepompong tidur pulas, hingga menjadi kupu-kupu indah!','[{\"text\": \"Kupu-kupu betina meletakkan telur di bawah daun hijau.\\nSetelah beberapa hari, telur menetas menjadi ulat (larva) yang lapar.\", \"title\": \"Telur Menetas Menjadi Ulat\", \"highlight\": \"Telur -> Ulat (Larva)\"}, {\"text\": \"Ulat yang kenyang akan menggantung dan membungkus diri menjadi kepompong (pupa).\\nDi dalam kepompong, tubuhnya berubah menjadi bersayap.\", \"title\": \"Tidur Damai dalam Kepompong\", \"highlight\": \"Kepompong (Pupa)\"}, {\"text\": \"Kepompong terbuka dan keluarlah kupu-kupu cantik (imago)!\\nKupu-kupu terbang menghisap nektar madu bunga yang manis.\", \"title\": \"Kupu-Kupu Dewasa Terbang Riang\", \"highlight\": \"Kupu-Kupu Dewasa (Imago)\"}]','https://images.unsplash.com/photo-1558642452-9d2a7deb7f62?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/ocWgSgMGxKA',10,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(5,1,3,2,'Bagian Tubuh Tumbuhan & Dapur Fotosintesis','bagian-tumbuhan-dan-fotosintesis','Akar menyerap air, batang mengalirkan zat hara, dan daun hijau memasak makanan sendiri dengan sinar matahari!','[{\"text\": \"Akar mencengkeram tanah dan menyerap air serta mineral.\\nBatang berdiri kokoh menopang daun, bunga, dan buah segar.\", \"title\": \"Akar, Batang, dan Daun Hijau\", \"highlight\": \"Akar Menyerap Air, Batang Menopang Ranting\"}, {\"text\": \"Daun memiliki zat hijau bernama klorofil untuk menangkap cahaya matahari.\\nDaun memasak air dan karbondioksida menjadi makanan tumbuhan.\", \"title\": \"Klorofil dan Sinar Matahari Pagi\", \"highlight\": \"Fotosintesis = Memasak Makanan Sendiri\"}, {\"text\": \"Proses fotosintesis melepaskan oksigen (O2) ke udara bebas.\\nOksigen inilah yang kita hirup agar tubuh tetap bugar dan sehat!\", \"title\": \"Menghasilkan Oksigen Segar\", \"highlight\": \"Tumbuhan Membuat Udara Jadi Sejuk\"}]','https://images.unsplash.com/photo-1518531933037-91b2f5f229cc?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/D1Ymc311XS8',10,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(6,1,4,1,'Materi & Tiga Wujud Benda serta Perubahannya','wujud-benda-dan-perubahannya','Segala sesuatu di alam berwujud padat, cair, atau gas. Benda dapat mencair, membeku, menguap, dan mengembun!','[{\"text\": \"Batu dan kayu berwujud padat dengan bentuk tetap.\\nAir minum berwujud cair mengikuti bentuk wadahnya.\\nUdara di dalam balon adalah gas yang mengisi seluruh ruangan.\", \"title\": \"Mengenal Padat, Cair, dan Gas\", \"highlight\": \"Padat (Bentuk Tetap), Cair (Mengalir), Gas (Menempati Ruang)\"}, {\"text\": \"Es batu dipanaskan akan mencair menjadi air jernih.\\nAir dimasukkan ke dalam freezer kulkas akan membeku menjadi es batu keras.\", \"title\": \"Mencair dan Membeku\", \"highlight\": \"Mencair (Padat ke Cair) & Membeku (Cair ke Padat)\"}, {\"text\": \"Air yang dimasak mendidih akan menguap menjadi uap air.\\nTitik-titik embun di dedaunan pagi hari adalah peristiwa mengembun.\", \"title\": \"Menguap dan Mengembun\", \"highlight\": \"Menguap (Cair ke Gas) & Mengembun (Gas ke Cair)\"}]','https://images.unsplash.com/photo-1517824806704-9040b037703b?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/n0FZhQ_GkKw',11,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(7,1,4,2,'Gaya, Gerak Benda & Macam Perubahan Energi','gaya-dan-perubahan-energi','Dorongan dan tarikan disebut gaya. Energi listrik bisa berubah menjadi cahaya, panas, dan gerak yang berguna.','[{\"text\": \"Kita memakai gaya otot saat menendang bola dan mengangkat buku.\\nGaya gesek pada rem sepeda membantu kita berhenti dengan aman.\\nMagnet bisa menarik klip kertas besi tanpa disentuh!\", \"title\": \"Gaya Otot, Gesek, dan Magnet\", \"highlight\": \"Gaya = Tarikan atau Dorongan pada Benda\"}, {\"text\": \"Setrika mengubah energi listrik menjadi panas untuk merapikan baju.\\nKipas angin mengubah energi listrik menjadi gerak putar yang sejuk.\\nLampu belajar mengubah listrik menjadi cahaya yang terang.\", \"title\": \"Keajaiban Perubahan Energi\", \"highlight\": \"Energi Listrik -> Gerak, Panas, dan Cahaya\"}]','https://images.unsplash.com/photo-1518770660439-4636190af475?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/libKPrr9QDA',9,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(8,1,4,3,'Denah, 8 Arah Mata Angin & Peninggalan Sejarah','denah-mata-angin-sejarah-lokal','Membaca arah kompas agar tidak tersesat, membedakan lingkungan alam dan buatan, serta melestarikan cagar budaya lokal.','[{\"text\": \"Matahari terbit di sebelah Timur dan tenggelam di sebelah Barat.\\nJika menghadap Timur, tangan kiri kita menunjuk Utara dan tangan kanan Selatan.\", \"title\": \"Arah Mata Angin dan Kompas\", \"highlight\": \"Utara, Timur, Selatan, Barat\"}, {\"text\": \"Gunung, sungai, dan pantai adalah lingkungan alam anugerah Tuhan.\\nWaduk, jembatan, dan gedung sekolah adalah lingkungan buatan manusia.\", \"title\": \"Lingkungan Alam vs Buatan\", \"highlight\": \"Alam (Terbentuk Sendiri) vs Buatan (Dibuat Manusia)\"}]','https://images.unsplash.com/photo-1524661135-423995f22d0b?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/2N4Xh4hN-6Y',8,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(9,1,5,1,'Sistem Organ Pencernaan & Pernapasan Manusia','sistem-organ-manusia','Jelajahi perjalanan makanan di mulut, lambung, dan usus, serta kerja paru-paru dan pembuluh darah kita!','[{\"text\": \"Gigi mengunyah makanan di mulut dibantu air liur.\\nMakanan meluncur lewat kerongkongan menuju lambung yang mencerna makanan halus.\", \"title\": \"Perjalanan Makanan dalam Tubuh\", \"highlight\": \"Mulut -> Kerongkongan -> Lambung -> Usus\"}, {\"text\": \"Usus halus menyerap nutrisi penting ke dalam aliran darah.\\nSisa makanan yang tidak terpakai diteruskan ke usus besar.\", \"title\": \"Penyerapan Zat Gizi di Usus Halus\", \"highlight\": \"Nutrisi Menjadi Energi Bermain dan Belajar\"}, {\"text\": \"Saat menarik napas, hidung menyaring udara kotor.\\nUdara masuk ke paru-paru dan terjadi pertukaran oksigen di gelembung alveolus.\", \"title\": \"Paru-Paru Penjaga Oksigen Kita\", \"highlight\": \"Alveolus = Tempat Pertukaran Oksigen & Karbondioksida\"}]','https://images.unsplash.com/photo-1579684385127-1ef15d508118?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/g3yW7B0bZ_Y',12,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(10,1,5,2,'Ekosistem, Jaring Makanan & Keseimbangan Alam','ekosistem-dan-jaring-makanan','Di sawah dan hutan, tumbuhan dan hewan saling membutuhkan dalam rantai makanan yang menjaga keseimbangan bumi.','[{\"text\": \"Tumbuhan hijau bertindak sebagai produsen karena membuat makanan sendiri.\\nHewan pemakan tumbuhan seperti belalang disebut konsumen tingkat 1.\", \"title\": \"Produsen dan Konsumen\", \"highlight\": \"Padi (Produsen) -> Belalang (Konsumen 1)\"}, {\"text\": \"Katak memakan belalang, ular memakan katak, dan burung elang memakan ular.\\nKetika elang mati, jamur dan bakteri pengurai mengembalikan zat hara ke tanah.\", \"title\": \"Pemangsa Puncak dan Pengurai\", \"highlight\": \"Konsumen Puncak (Elang) & Pengurai (Jamur/Bakteri)\"}]','https://images.unsplash.com/photo-1448375240586-882707db888b?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/WbHj9fM_fO0',10,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(11,1,6,1,'Menjelajahi Tata Surya, Planet & Peristiwa Gerhana','menjelajahi-tata-surya-dan-planet','Naik roket antariksa mengitari matahari, menjelajahi 8 planet megah, dan menyaksikan gerhana bulan yang spektakuler!','[{\"text\": \"Matahari adalah bintang raksasa yang menjadi pusat gravitasi tata surya.\\nPlanet terdekat adalah Merkurius, disusul Venus, Bumi, Mars, Jupiter, Saturnus, Uranus, dan Neptunus.\", \"title\": \"Matahari & 8 Planet Pengorbit\", \"highlight\": \"Jupiter Terbesar, Saturnus Punya Cincin Indah\"}, {\"text\": \"Bumi berputar pada porosnya (rotasi) selama 24 jam menyebabkan siang dan malam.\\nBumi mengelilingi matahari (revolusi) selama 1 tahun menyebabkan pergantian musim.\", \"title\": \"Rotasi dan Revolusi Bumi\", \"highlight\": \"Rotasi (Siang & Malam), Revolusi (Pergantian Musim)\"}, {\"text\": \"Ketika bumi berada tepat di antara matahari dan bulan, terjadilah gerhana bulan.\\nKetika bulan berada di antara matahari dan bumi, sinar matahari terhalang menjadi gerhana matahari.\", \"title\": \"Gerhana Bulan dan Gerhana Matahari\", \"highlight\": \"Posisi Garis Lurus Matahari, Bumi, dan Bulan\"}]','https://images.unsplash.com/photo-1614728894747-a83421e2b9c9?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/libKPrr9QDA',14,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(12,1,6,2,'Fisika Dasar: Sifat Cahaya, Gelombang Bunyi & Magnet','sifat-cahaya-bunyi-magnet','Cahaya merambat lurus dan dapat dibiaskan, bunyi dihasilkan dari getaran benda, dan magnet memiliki kutub utara-selatan.','[{\"text\": \"Cahaya merambat lurus dan menembus benda bening seperti kaca jendela.\\nCahaya dapat dibiaskan air sehingga pensil di gelas tampak patah, dan membentuk pelangi!\", \"title\": \"Keajaiban Sifat Cahaya\", \"highlight\": \"Cahaya Merambat Lurus, Menembus Benda Bening, & Dibiaskan\"}, {\"text\": \"Petikan senar gitar dan pukulan drum membuat udara bergetar menghasilkan bunyi.\\nBunyi merambat melalui udara, benda padat, dan zat cair, tetapi tidak di ruang hampa.\", \"title\": \"Getaran Bunyi dan Resonansi\", \"highlight\": \"Bunyi Berasal dari Benda yang Bergetar\"}]','https://images.unsplash.com/photo-1509228468518-180dd4864904?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/D1Ymc311XS8',11,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(13,1,6,3,'Geografi Nusantara, Proklamasi & Kerjasama ASEAN','geografi-proklamasi-asean','Kekayaan letak geografis Indonesia, detik-detik kemerdekaan 17 Agustus 1945, dan persahabatan negara Asia Tenggara!','[{\"text\": \"Indonesia berada di antara Benua Asia dan Australia, serta Samudra Hindia dan Pasifik.\\nIklim tropis membuat tanah kita subur kaya rempah-rempah.\", \"title\": \"Letak Silang Geografis Indonesia\", \"highlight\": \"Zamrud Khatulistiwa di Jalur Perdagangan Dunia\"}, {\"text\": \"Pada 17 Agustus 1945, Ir. Soekarno dan Drs. Mohammad Hatta membacakan teks proklamasi.\\nBendera Merah Putih dikibarkan dengan khidmat diiringi lagu Indonesia Raya.\", \"title\": \"Detik-Detik Proklamasi Kemerdekaan\", \"highlight\": \"17 Agustus 1945 = Hari Kemerdekaan Indonesia\"}, {\"text\": \"Indonesia adalah salah satu pendiri ASEAN bersama Malaysia, Singapura, Filipina, dan Thailand.\\nKita bekerjasama menjaga perdamaian, ekonomi, dan pendidikan yang maju.\", \"title\": \"Persahabatan Negara Anggota ASEAN\", \"highlight\": \"ASEAN = Perhimpunan Bangsa Asia Tenggara\"}]','https://images.unsplash.com/photo-1577896851231-70ef18881754?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/41fS2G4d538',12,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(14,2,1,1,'Bilangan Cacah & Membandingkan Angka 1-100','bilangan-cacah-dan-membandingkan-angka','Belajar menghafal angka 1 sampai 100, menghitung maju mundur, serta membandingkan lebih banyak dan lebih sedikit.','[{\"text\": \"Ayo hitung jari tangan dan kancing bajumu!\\nAngka 1, 2, 3, 4, 5 sampai 20 punya bentuk yang unik dan mudah diingat.\", \"title\": \"Mengenal Lambang Angka 1-20\", \"highlight\": \"Menulis dan Membaca Angka Dasar\"}, {\"text\": \"Kelinci punya 8 wortel, sedangkan kura-kura punya 5 wortel.\\n8 wortel LEBIH BANYAK daripada 5 wortel kelinci!\", \"title\": \"Membandingkan Banyak Benda\", \"highlight\": \"Lebih Banyak, Lebih Sedikit, atau Sama Banyak\"}]','https://images.unsplash.com/photo-1596495578065-6e0763fa1178?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/Fe8u2I3vmHU',6,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(15,2,1,2,'Penjumlahan & Pengurangan Ceria Buah Segar','penjumlahan-dan-pengurangan-dasar','Menghitung apel manis di keranjang memakai tanda tambah (+) dan menghitung sisa kue dengan tanda kurang (-).','[{\"text\": \"Ada 3 apel di atas meja, lalu ibu menaruh 2 apel lagi.\\n3 apel + 2 apel = 5 apel manis terkumpul!\", \"title\": \"Kelinci Menghitung Apel Merah (+)\", \"highlight\": \"3 + 2 = 5 Buah Apel Segar\"}, {\"text\": \"Kakak punya 6 buah donat cokelat yang lezat.\\n2 donat diberikan kepada adik tercinta.\\n6 - 2 = 4 donat yang tersisa di piring.\", \"title\": \"Kue Donat Berkurang (-)\", \"highlight\": \"6 - 2 = 4 Donat Tersisa\"}]','https://images.unsplash.com/photo-1560806887-1e4cd0b6cbd6?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/Fe8u2I3vmHU',7,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(16,2,2,1,'Membaca Jam Tepat & Mengenal Uang Rupiah','membaca-jam-dan-uang-rupiah','Kapan waktu berangkat sekolah? Belajar membaca jarum jam dinding dan mengenal uang koin serta kertas rupiah!','[{\"text\": \"Jarum pendek menunjuk angka jam, jarum panjang menunjuk menit.\\nJika jarum pendek di angka 7 dan jarum panjang di angka 12, maka sekarang pukul 07.00 tepat!\", \"title\": \"Jarum Pendek & Jarum Panjang Jam\", \"highlight\": \"Pukul 07.00 = Waktu Masuk Sekolah\"}, {\"text\": \"Ada uang koin Rp500 dan Rp1.000 dari logam berkilau.\\nAda juga uang kertas Rp2.000, Rp5.000, hingga Rp10.000 untuk jajan sehat di kantin.\", \"title\": \"Mengenal Pecahan Uang Rupiah\", \"highlight\": \"Rupiah (Rp) adalah Mata Uang Indonesia\"}]','https://images.unsplash.com/photo-1509228468518-180dd4864904?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/n0FZhQ_GkKw',8,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(17,2,2,2,'Geometri Dasar: Segitiga, Persegi & Lingkaran','geometri-dasar-bangun-datar','Buku kita berbentuk persegi panjang, roda sepeda bundar seperti lingkaran, dan potongan pizza mirip segitiga!','[{\"text\": \"Segitiga memiliki 3 sisi dan 3 titik sudut.\\nPersegi memiliki 4 sisi yang sama panjang.\\nLingkaran tidak memiliki sudut, bentuknya bulat mulus seperti roda sepeda.\", \"title\": \"Segitiga, Persegi, dan Lingkaran\", \"highlight\": \"Mengenal Sisi dan Sudut Bangun Datar\"}, {\"text\": \"Kotak kado berbentuk kubus dan kardus pasta gigi berbentuk balok.\\nBola kasti berbentuk bulat sempurna yang bisa menggelinding cepat.\", \"title\": \"Bangun Ruang Sederhana\", \"highlight\": \"Kubus, Balok, dan Bola\"}]','https://images.unsplash.com/photo-1509228468518-180dd4864904?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/n0FZhQ_GkKw',8,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(18,2,2,3,'Pengukuran Panjang & Berat dengan Alat Baku','pengukuran-panjang-dan-berat','Mengukur panjang meja dengan jengkal tangan vs penggaris sentimeter, serta menimbang berat semangka dengan kilogram!','[{\"text\": \"Jengkal jari tangan dan langkah kaki adalah alat ukur tidak baku karena ukuran tangan tiap anak berbeda.\\nPenggaris dan meteran adalah alat ukur baku bersatuan sentimeter (cm) dan meter (m).\", \"title\": \"Alat Ukur Panjang Tidak Baku & Baku\", \"highlight\": \"1 Meter (m) = 100 Sentimeter (cm)\"}, {\"text\": \"Timbangan digunakan untuk mengukur berat beras, buah, dan tubuh kita.\\nSatuan berat baku yang sering kita gunakan adalah gram (g) dan kilogram (kg).\", \"title\": \"Menimbang Berat dengan Kilogram (kg)\", \"highlight\": \"1 Kilogram (kg) = 1.000 Gram (g)\"}]','https://images.unsplash.com/photo-1596495578065-6e0763fa1178?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/Fe8u2I3vmHU',8,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(19,2,3,1,'Bilangan Ribuan & Mengenal Pecahan (1/2, 1/3, 1/4)','bilangan-ribuan-dan-pecahan-senilai','Membaca angka hingga 10.000 dan membagi seloyang pizza secara adil dengan pecahan setengah, sepertiga, dan seperempat!','[{\"text\": \"Pada angka 4.520, angka 4 menempati ribuan, 5 ratusan, 2 puluhan, dan 0 satuan.\\nDibaca \'Empat ribu lima ratus dua puluh\'.\", \"title\": \"Membaca Nilai Tempat Ribuan\", \"highlight\": \"Ribuan, Ratusan, Puluhan, Satuan\"}, {\"text\": \"Jika 1 pizza dipotong 2 bagian sama besar, satu potong bernilai 1/2 (setengah).\\nJika dipotong 4 bagian sama besar, satu potong bernilai 1/4 (seperempat).\", \"title\": \"Memotong Pizza Jadi Pecahan (1/2 & 1/4)\", \"highlight\": \"1/2 sama besarnya dengan 2/4 (Pecahan Senilai)\"}]','https://images.unsplash.com/photo-1513104890138-7c749659a591?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/n0FZhQ_GkKw',10,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(20,2,3,2,'Perkalian & Pembagian Bersusun yang Menyenangkan','perkalian-dan-pembagian-bersusun','Perkalian adalah penjumlahan berulang, sedangkan pembagian adalah membagi sama rata secara bersusun!','[{\"text\": \"4 x 3 artinya 3 + 3 + 3 + 3 = 12.\\nDengan menghafal tabel perkalian 1 sampai 10, berhitung menjadi sangat cepat!\", \"title\": \"Perkalian sebagai Penjumlahan Berulang\", \"highlight\": \"4 x 3 = 12 (Tiga Ditambahkan Sebanyak 4 Kali)\"}, {\"text\": \"Ada 24 kelereng yang ingin dibagikan kepada 4 teman sama rata.\\n24 dibagi 4 = 6 kelereng untuk tiap teman tanpa ada sisa.\", \"title\": \"Pembagian Porogapit Bersusun\", \"highlight\": \"24 : 4 = 6\"}]','https://images.unsplash.com/photo-1509228468518-180dd4864904?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/n0FZhQ_GkKw',10,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(21,2,4,1,'KPK dan FPB Dasar Menggunakan Pohon Faktor','kpk-dan-fpb-dasar','Temukan kelipatan terkecil dan faktor persekutuan terbesar bilangan memakai pohon faktor bilangan prima!','[{\"text\": \"Bilangan prima adalah bilangan yang hanya bisa dibagi 1 dan dirinya sendiri: 2, 3, 5, 7, 11...\\nFaktor dari 12 adalah 1, 2, 3, 4, 6, dan 12.\", \"title\": \"Mengenal Bilangan Prima & Faktor\", \"highlight\": \"Bilangan Prima: 2, 3, 5, 7, 11, 13...\"}, {\"text\": \"KPK dicari dari perkalian semua faktor prima dengan pangkat terbesar.\\nFPB dicari dari faktor prima yang sama dengan pangkat terkecil.\", \"title\": \"Menentukan KPK dan FPB\", \"highlight\": \"KPK (Kelipatan Persekutuan Terkecil) & FPB (Faktor Terbesar)\"}]','https://images.unsplash.com/photo-1596495578065-6e0763fa1178?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/n0FZhQ_GkKw',11,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(22,2,4,2,'Keliling & Luas Persegi, Persegi Panjang, Segitiga','keliling-dan-luas-bangun-datar','Mengelilingi batas lapangan sepak bola dan menghitung luas ubin lantai dengan rumus perkalian praktis!','[{\"text\": \"Keliling adalah jumlah panjang seluruh sisi terluar bangun datar.\\nKeliling persegi = 4 x sisi. Keliling persegi panjang = 2 x (panjang + lebar).\", \"title\": \"Keliling Bangun Datar\", \"highlight\": \"Keliling = Menjumlahkan Semua Batas Sisi\"}, {\"text\": \"Luas persegi = sisi x sisi.\\nLuas persegi panjang = panjang x lebar.\\nLuas segitiga = (alas x tinggi) : 2.\", \"title\": \"Luas Bangun Datar\", \"highlight\": \"Luas = Mengukur Seluruh Permukaan Bagian Dalam\"}]','https://images.unsplash.com/photo-1509228468518-180dd4864904?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/n0FZhQ_GkKw',11,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(23,2,4,3,'Garis, Sudut & Menyajikan Diagram Batang','garis-sudut-dan-pengolahan-data','Mengenal sudut siku-siku 90 derajat, sudut lancip, tumpul, serta menyajikan data hobi teman dalam diagram batang!','[{\"text\": \"Sudut siku-siku besarnya tepat 90 derajat (seperti pojok buku).\\nSudut lancip lebih kecil dari 90 derajat.\\nSudut tumpul lebih besar dari 90 derajat.\", \"title\": \"Macam-Macam Besar Sudut\", \"highlight\": \"Sudut Lancip (<90°), Siku-Siku (90°), Tumpul (>90°)\"}, {\"text\": \"Tinggi batang tegak menunjukkan banyaknya jumlah data.\\nDengan diagram batang, kita bisa langsung melihat hobi apa yang paling disukai teman-teman!\", \"title\": \"Membaca Diagram Batang\", \"highlight\": \"Diagram Batang Memudahkan Kita Membaca Informasi\"}]','https://images.unsplash.com/photo-1551288049-bebda4e38f71?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/n0FZhQ_GkKw',10,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(24,2,5,1,'Operasi Hitung Campuran & Bilangan Bulat Negatif','operasi-hitung-campuran-dan-bilangan-bulat','Jelajahi garis bilangan di bawah angka nol (negatif) dan urutan pengerjaan operasi hitung kurung, kali, bagi, tambah, kurang.','[{\"text\": \"Angka di sebelah kanan nol bernilai positif (1, 2, 3...).\\nAngka di sebelah kiri nol bernilai negatif (-1, -2, -3...), seperti suhu es beku di bawah nol derajat.\", \"title\": \"Garis Bilangan Bulat Positif dan Negatif\", \"highlight\": \"Makin ke kiri nilai makin kecil, makin ke kanan makin besar\"}, {\"text\": \"Kerjakan tanda kurung terlebih dahulu.\\nLalu operasi kali (x) dan bagi (:) yang setingkat.\\nTerakhir kerjakan operasi tambah (+) dan kurang (-).\", \"title\": \"Aturan Urutan Operasi Hitung\", \"highlight\": \"Kurung -> Kali & Bagi -> Tambah & Kurang\"}]','https://images.unsplash.com/photo-1596495578065-6e0763fa1178?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/n0FZhQ_GkKw',12,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(25,2,5,2,'Pecahan Beda Penyebut, Desimal & Persentase (%)','pecahan-beda-penyebut-dan-persen','Menyamakan penyebut dengan KPK, mengubah pecahan ke desimal berkoma, dan menghitung diskon belanja dengan persen.','[{\"text\": \"Untuk menghitung 1/2 + 1/3, kita harus menyamakan penyebutnya menggunakan KPK dari 2 dan 3, yaitu 6.\\n1/2 menjadi 3/6, dan 1/3 menjadi 2/6. Hasilnya adalah 5/6!\", \"title\": \"Menjumlahkan Pecahan Beda Penyebut\", \"highlight\": \"1/2 + 1/3 = 3/6 + 2/6 = 5/6\"}, {\"text\": \"Pecahan 1/2 sama dengan desimal 0,5 atau 50%.\\nPecahan 1/4 sama dengan desimal 0,25 atau 25%.\", \"title\": \"Desimal dan Persentase (%)\", \"highlight\": \"Persen (%) artinya Per Seratus (/100)\"}]','https://images.unsplash.com/photo-1513104890138-7c749659a591?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/n0FZhQ_GkKw',12,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(26,2,5,3,'Skala Peta, Jarak Sebenarnya & Kecepatan Tempuh','skala-jarak-dan-kecepatan','Membaca skala peta 1:1.000.000 untuk mengetahui jarak kota yang sebenarnya, serta menghitung kecepatan laju kendaraan.','[{\"text\": \"Skala 1 : 100.000 artinya 1 cm di peta mewakili 100.000 cm (atau 1 km) jarak sebenarnya di bumi.\\nJarak Sebenarnya = Jarak Peta x Skala.\", \"title\": \"Memahami Skala Peta\", \"highlight\": \"Skala = Jarak pada Peta : Jarak Sebenarnya\"}, {\"text\": \"Kecepatan adalah jarak yang ditempuh per satuan waktu (km/jam).\\nJika mobil melaju 60 km/jam selama 2 jam, maka jarak yang ditempuh adalah 120 km.\", \"title\": \"Segitiga Rumus Kecepatan (J = K x W)\", \"highlight\": \"Jarak = Kecepatan x Waktu\"}]','https://images.unsplash.com/photo-1524661135-423995f22d0b?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/2N4Xh4hN-6Y',11,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(27,2,6,1,'Volume & Luas Permukaan Bangun Ruang (Kubus s/d Tabung)','volume-bangun-ruang','Menghitung muatan air dalam bak kubus, volume kardus balok, kaleng tabung, dan kerucut es krim dengan rumus teruji!','[{\"text\": \"Volume Kubus = rusuk x rusuk x rusuk (s x s x s).\\nVolume Balok = panjang x lebar x tinggi (p x l x t).\\nSatuan volume dinyatakan dalam sentimeter kubik (cm³) atau liter.\", \"title\": \"Volume Kubus dan Balok\", \"highlight\": \"1 Liter = 1 Desimeter Kubik (dm³)\"}, {\"text\": \"Volume Tabung = luas alas x tinggi = pi x r x r x t.\\nVolume Kerucut adalah sepertiga dari tabung = 1/3 x pi x r x r x t.\", \"title\": \"Volume Tabung dan Kerucut\", \"highlight\": \"Tabung (Alas Lingkaran) & Kerucut (1/3 Volume Tabung)\"}]','https://images.unsplash.com/photo-1509228468518-180dd4864904?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/n0FZhQ_GkKw',13,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(28,2,6,2,'Unsur Lingkaran & Statistika (Mean, Median, Modus)','lingkaran-dan-statistika-data','Menghitung luas lingkaran dengan rumus pi x r x r, serta menemukan nilai rata-rata (mean), nilai tengah, dan modus data.','[{\"text\": \"Diameter (d) adalah garis lurus yang membelah lingkaran melewati titik pusat.\\nJari-jari (r) adalah setengah dari diameter. Keliling = 2 x pi x r. Luas = pi x r².\", \"title\": \"Unsur Lingkaran (Jari-Jari & Diameter)\", \"highlight\": \"Nilai pi adalah 22/7 atau 3,14\"}, {\"text\": \"Mean = Rata-rata (jumlah semua nilai dibagi banyak data).\\nMedian = Nilai yang berada tepat di tengah setelah data diurutkan.\\nModus = Nilai angka yang paling sering muncul.\", \"title\": \"Mean, Median, dan Modus\", \"highlight\": \"Mean (Rata-rata), Median (Nilai Tengah), Modus (Sering Muncul)\"}]','https://images.unsplash.com/photo-1551288049-bebda4e38f71?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/n0FZhQ_GkKw',13,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(29,3,1,1,'Membaca Permulaan: Huruf Vokal, Konsonan & Suku Kata','membaca-permulaan-dan-suku-kata','Mengenal huruf vokal a-i-u-e-o, menggabungkannya dengan huruf konsonan, dan membaca kata pertama dengan riang!','[{\"text\": \"Huruf vokal adalah: A, I, U, E, dan O.\\nApel, Ikan, Udang, Elang, dan Onta diawali huruf vokal yang ceria!\", \"title\": \"5 Huruf Vokal yang Ramah\", \"highlight\": \"A - I - U - E - O\"}, {\"text\": \"B-A dibaca BA, C-A dibaca CA. BA-CA menjadi BACA!\\nB-U dibaca BU, K-U dibaca KU. BU-KU menjadi BUKU!\\nKamu hebat sudah bisa membaca kata pertamamu!\", \"title\": \"Menggabungkan Suku Kata Menjadi Kata\", \"highlight\": \"Ba-ca Bu-ku = Baca Buku\"}]','https://images.unsplash.com/photo-1503676260728-1c00da094a0b?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/Fe8u2I3vmHU',7,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(30,3,1,2,'Tanda Baca Titik, Huruf Kapital & Tiga Kata Ajaib','tanda-baca-dasar-dan-tiga-kata-ajaib','Kapan memakai huruf kapital dan tanda titik? Serta membiasakan tiga kata ajaib: maaf, tolong, dan terima kasih.','[{\"text\": \"Huruf awal kalimat dan nama orang harus memakai huruf besar (kapital).\\nDi akhir kalimat berita, selalu bubuhkan tanda titik (.) sebagai tanda berhenti membaca.\", \"title\": \"Huruf Kapital dan Tanda Titik (.)\", \"highlight\": \"Contoh: Budi menyiram tanaman.\"}, {\"text\": \"Katakan \'Tolong\' saat meminta bantuan teman.\\nKatakan \'Maaf\' saat berbuat kekeliruan secara tidak sengaja.\\nKatakan \'Terima kasih\' saat menerima pertolongan atau hadiah.\", \"title\": \"Tiga Kata Ajaib Anak Santun\", \"highlight\": \"Tolong, Maaf, dan Terima Kasih\"}]','https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/Fe8u2I3vmHU',7,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(31,3,2,1,'Mendeskripsikan Ciri Benda & Dongeng Fabel Kancil','mendeskripsikan-benda-dan-fabel','Belajar menjelaskan bentuk, warna, dan kegunaan benda kesayangan, serta memetik pesan moral dari cerita fabel hewan.','[{\"text\": \"Tas sekolahku berwarna biru tua, memiliki dua kantong, dan dipakai untuk membawa buku tulis.\\nMenjelaskan ciri benda membantu teman mengenali benda yang kita maksud.\", \"title\": \"Mendeskripsikan Benda di Sekitar\", \"highlight\": \"Sebutkan Bentuk, Warna, dan Kegunaannya\"}, {\"text\": \"Fabel adalah cerita fiksi dengan tokoh binatang yang bisa berbicara seperti manusia.\\nKancil yang cerdik mengajarkan kita untuk memakai akal sehat dan tidak boleh bersikap sombong.\", \"title\": \"Dongeng Fabel Hewan Penuh Pesan Moral\", \"highlight\": \"Fabel = Cerita Tokoh Hewan yang Bijaksana\"}]','https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/ocWgSgMGxKA',8,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(32,3,3,1,'Menemukan Gagasan Pokok & Kalimat Pendukung','ide-pokok-dan-kalimat-pendukung','Rahasia menemukan ide utama dalam paragraf bacaan dan membedakannya dengan kalimat penjelas yang menyertainya.','[{\"text\": \"Gagasan pokok adalah inti sari masalah yang dibahas dalam suatu paragraf.\\nBiasanya terletak di kalimat pertama (deduktif) atau di akhir paragraf (induktif).\", \"title\": \"Apa itu Gagasan Pokok?\", \"highlight\": \"Gagasan Pokok = Inti Pembahasan Paragraf\"}, {\"text\": \"Kalimat pendukung bertugas menjelaskan gagasan pokok dengan contoh, alasan, dan rincian yang lebih lengkap.\", \"title\": \"Kalimat Pendukung / Penjelas\", \"highlight\": \"Kalimat Pendukung Memperjelas Ide Utama\"}]','https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/ocWgSgMGxKA',9,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(33,3,3,2,'Teks Petunjuk Prosedur & Menulis Surat Pribadi','teks-petunjuk-dan-surat-pribadi','Menyusun langkah membuat layang-layang secara urut dan menulis surat kabar penuh rindu untuk kakek-nenek.','[{\"text\": \"Teks petunjuk memuat langkah-langkah kerja yang berurutan menggunakan kalimat perintah yang santun dan jelas.\\nContoh: \'Pertama, rekatkan bambu dengan benang, lalu tempelkan kertas minyak.\'\", \"title\": \"Menyusun Teks Petunjuk (Prosedur)\", \"highlight\": \"Langkah-Langkah Harus Runtut dan Jelas\"}, {\"text\": \"Surat pribadi diawali tanggal surat, salam pembuka, kabar cerita menyenangkan, dan salam penutup yang manis.\", \"title\": \"Menulis Surat untuk Sahabat / Keluarga\", \"highlight\": \"Salam Pembuka -> Isi Cerita -> Salam Penutup\"}]','https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/ocWgSgMGxKA',9,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(34,3,4,1,'Mendeklamasikan Puisi Anak & Karakter Tokoh Fiksi','puisi-anak-dan-tokoh-fiksi','Membaca bait puisi indah dengan mimik wajah riang, intonasi tepat, serta mengenali watak tokoh dalam cerpen.','[{\"text\": \"Puisi disusun dari bait-bait kata yang berima dan penuh ungkapan hati.\\nSaat membacakan puisi, perhatikan lafal, jeda, intonasi, dan ekspresi wajah yang pas.\", \"title\": \"Keindahan Bait Puisi Anak\", \"highlight\": \"Lafal, Intonasi, Jeda, dan Ekspresi Wajah\"}, {\"text\": \"Tokoh protagonis adalah tokoh berwatak baik yang disukai pembaca.\\nTokoh antagonis adalah tokoh penentang yang berwatak kurang baik.\", \"title\": \"Tokoh Protagonis dan Antagonis\", \"highlight\": \"Protagonis (Baik) vs Antagonis (Penentang)\"}]','https://images.unsplash.com/photo-1474932430478-367dbb6832c1?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/ocWgSgMGxKA',10,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(35,3,5,1,'Teks Eksplanasi Fenomena Alam & Fakta Sejarah','teks-eksplanasi-dan-nonfiksi','Mencari fakta sebab-akibat terjadinya pelangi, letusan gunung berapi, serta peristiwa bersejarah yang nyata.','[{\"text\": \"Teks eksplanasi menjelaskan proses terjadinya fenomena alam atau sosial secara ilmiah.\\nStrukturnya terdiri dari pernyataan umum, deretan penjelasan sebab-akibat, dan kesimpulan interpretasi.\", \"title\": \"Struktur Teks Eksplanasi Ilmiah\", \"highlight\": \"Pernyataan Umum -> Sebab-Akibat -> Kesimpulan\"}, {\"text\": \"Fakta adalah kenyataan yang benar-benar terjadi dan dapat dibuktikan kebenarannya.\\nOpini adalah pendapat atau perkiraan seseorang yang belum tentu terjadi.\", \"title\": \"Membedakan Fakta dan Opini\", \"highlight\": \"Fakta (Kenyataan Nyata) vs Opini (Pendapat Pribadi)\"}]','https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/ocWgSgMGxKA',11,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(36,3,5,2,'Struktur Pantun Nasehat Bersajak a-b-a-b & Makna Kias','pantun-nasehat-dan-puisi','Membedah sampiran dan isi pantun nusantara, membuat pantun berbalas jenaka, dan memahami ungkapan kiasan.','[{\"text\": \"Satu bait pantun terdiri dari 4 baris dengan rima persajakan a-b-a-b.\\nBaris 1 dan 2 disebut sampiran, sedangkan baris 3 dan 4 adalah isi pantun yang memuat nasehat berharga.\", \"title\": \"Ciri-Ciri Khas Pantun Indonesia\", \"highlight\": \"Baris 1-2 (Sampiran), Baris 3-4 (Isi Pantun)\"}, {\"text\": \"Ungkapan kiasan seperti \'ringan tangan\' artinya suka menolong teman.\\n\'Besar kepala\' artinya sombong, sedangkan \'rendah hati\' artinya tidak sombong.\", \"title\": \"Makna Kiasan Penuh Makna\", \"highlight\": \"Rendah Hati (Tidak Sombong) & Ringan Tangan (Suka Menolong)\"}]','https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/ocWgSgMGxKA',10,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(37,3,6,1,'Menyusun Naskah Pidato & Menganalisis Pesan Iklan','naskah-pidato-dan-pesan-iklan','Belajar berbicara di depan umum dengan naskah pidato terstruktur, serta menganalisis pesan ajakan pada iklan media.','[{\"text\": \"Pidato diawali salam pembuka dan rasa syukur kepada Tuhan.\\nBagian isi memuat pesan inti ajakan, lalu diakhiri permohonan maaf dan salam penutup yang santun.\", \"title\": \"Struktur Teks Pidato yang Baik\", \"highlight\": \"Pembuka -> Isi Pidato -> Penutup\"}, {\"text\": \"Iklan layanan masyarakat mengajak masyarakat melakukan kebaikan bersama.\\nContoh: ajakan menghemat air bersih, membuang sampah pada tempatnya, dan gemar membaca buku.\", \"title\": \"Iklan Layanan Masyarakat\", \"highlight\": \"Iklan Bersifat Persuasif (Mengajak dan Membujuk)\"}]','https://images.unsplash.com/photo-1505373877841-8d25f7d46678?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/ocWgSgMGxKA',11,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(38,4,1,1,'5 Simbol Sila Pancasila di Perisai Burung Garuda','simbol-pancasila-dan-hidup-rukun','Mengenal Bintang emas, Rantai baja, Pohon Beringin, Kepala Banteng, dan Padi-Kapas sebagai lambang kebanggaan!','[{\"text\": \"Garuda Pancasila adalah lambang negara Indonesia yang gagah perkasa.\\nDi dadanya ada perisai yang memuat 5 simbol sila yang luhur.\", \"title\": \"Burung Garuda Lambang Negara Kita\", \"highlight\": \"Garuda Pancasila Lambang Negara Indonesia\"}, {\"text\": \"Sila 1: Bintang emas berkilau.\\nSila 2: Rantai emas yang tersambung erat.\\nSila 3: Pohon Beringin yang rindang teduh.\\nSila 4: Kepala Banteng perkasa.\\nSila 5: Padi dan Kapas kemakmuran.\", \"title\": \"5 Simbol Sila Pancasila\", \"highlight\": \"Bintang, Rantai, Beringin, Banteng, Padi & Kapas\"}]','https://images.unsplash.com/photo-1577896851231-70ef18881754?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/41fS2G4d538',8,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(39,4,2,1,'Tata Tertib di Rumah & Menjaga Aturan Kelas','aturan-rumah-dan-sekolah','Aturan dibuat agar hidup kita tertib, aman, dan tenteram. Menepati janji serta menghargai waktu belajar di sekolah.','[{\"text\": \"Bangun pagi tepat waktu, merapikan selimut tempat tidur, dan mencuci piring setelah makan.\\nAturan di rumah membuat keluarga rukun dan rumah selalu bersih rapi.\", \"title\": \"Aturan Disiplin di Rumah\", \"highlight\": \"Aturan Membuat Kehidupan Jadi Tertib\"}, {\"text\": \"Mendengarkan penjelasan bapak dan ibu guru dengan saksama.\\nMengangkat tangan terlebih dahulu sebelum bertanya atau berpendapat.\", \"title\": \"Tertib Saat Berada di Kelas\", \"highlight\": \"Saling Menghormati Antara Guru dan Murid\"}]','https://images.unsplash.com/photo-1580582932707-520aed937b7b?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/41fS2G4d538',8,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(40,4,3,1,'Makna Ikrar Sumpah Pemuda & Keragaman Budaya','sumpah-pemuda-dan-keragaman-budaya','Satu nusa, satu bangsa, satu bahasa persatuan Indonesia! Menghargai ribuan suku, tarian adat, dan pakaian daerah.','[{\"text\": \"Para pemuda dari berbagai daerah berkumpul mengikrarkan janji Sumpah Pemuda.\\nKita bersumpah menjunjung tanah air yang satu, bangsa yang satu, dan bahasa persatuan Indonesia.\", \"title\": \"Peristiwa Bersejarah 28 Oktober 1928\", \"highlight\": \"28 Oktober = Hari Sumpah Pemuda\"}, {\"text\": \"Dari Sabang sampai Merauke ada suku Jawa, Sunda, Batak, Dayak, Bugis, hingga Papua.\\nPerbedaan suku membuat Indonesia kaya warna dan sangat indah!\", \"title\": \"Kekayaan Suku dan Tarian Nusantara\", \"highlight\": \"Beragam Suku, Satu Keluarga Besar Indonesia\"}]','https://images.unsplash.com/photo-1577896851231-70ef18881754?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/41fS2G4d538',9,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(41,4,4,1,'Hak dan Kewajiban Anak di Rumah & Sekolah','hak-dan-kewajiban-anak','Kewajiban harus dikerjakan dengan penuh tanggung jawab sebelum kita menuntut hak yang kita miliki.','[{\"text\": \"Kewajiban adalah sesuatu yang harus kita laksanakan dengan penuh tanggung jawab.\\nHak adalah sesuatu yang patut kita terima setelah menuntaskan kewajiban.\", \"title\": \"Apa itu Hak dan Kewajiban?\", \"highlight\": \"Kewajiban Dulu, Baru Menuntut Hak\"}, {\"text\": \"Kewajiban murid adalah belajar giat dan menjaga kebersihan sekolah.\\nHak murid adalah mendapatkan bimbingan guru dan fasilitas belajar yang nyaman.\", \"title\": \"Contoh Nyata di Sekolah\", \"highlight\": \"Keseimbangan Antara Hak dan Kewajiban\"}]','https://images.unsplash.com/photo-1503676260728-1c00da094a0b?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/41fS2G4d538',9,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(42,4,5,1,'Semangat Gotong Royong & Sejarah BPUPKI/PPKI','gotong-royong-dan-sejarah-pancasila','Kisah tokoh bangsa merumuskan dasar negara Pancasila dan indahnya budaya gotong royong membersihkan kampung.','[{\"text\": \"BPUPKI dibentuk untuk mempersiapkan kemerdekaan Indonesia.\\nPada 1 Juni 1945, Ir. Soekarno menyampaikan gagasan dasar negara yang dinamakan Pancasila.\", \"title\": \"Sejarah Lahirnya Pancasila\", \"highlight\": \"1 Juni = Hari Lahir Pancasila\"}, {\"text\": \"Berat sama dipikul, ringan sama dijinjing.\\nGotong royong membuat pekerjaan berat menjadi cepat selesai dan mempererat tali persaudaraan.\", \"title\": \"Nilai Luhur Gotong Royong\", \"highlight\": \"Berat Sama Dipikul, Ringan Sama Dijinjing\"}]','https://images.unsplash.com/photo-1577896851231-70ef18881754?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/41fS2G4d538',10,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(43,4,6,1,'Menjaga Persatuan & Keutuhan NKRI Bhinneka Tunggal Ika','persatuan-nkri-dan-bhinneka-tunggal-ika','Berbeda-beda tetapi tetap satu jua. Menjaga kerukunan antarumat beragama dan rasa bangga terhadap bangsa Indonesia!','[{\"text\": \"Semboyan ini berasal dari Kitab Sutasoma karya Mpu Tantular.\\nArtinya \'Meskipun berbeda-beda, pada hakikatnya bangsa Indonesia tetap satu kesatuan.\'\", \"title\": \"Makna Semboyan Bhinneka Tunggal Ika\", \"highlight\": \"Berbeda-beda Tetapi Tetap Satu Jua\"}, {\"text\": \"Tidak mengejek teman yang berbeda suku atau agama, menjauhi pertikaian, dan giat mengukir prestasi demi mengharumkan nama bangsa.\", \"title\": \"Peran Pelajar Menjaga Persatuan\", \"highlight\": \"Toleransi Adalah Kunci Kerukunan Bangsa\"}]','https://images.unsplash.com/photo-1577896851231-70ef18881754?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/41fS2G4d538',10,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(44,5,1,1,'Alphabet Song, Friendly Greetings & Cheerful Colors','alphabet-greetings-and-colors','Sing the ABC song happily, say Good Morning to your friends, and name vibrant rainbow colors in English!','[{\"text\": \"Good morning! (Selamat pagi)\\nGood afternoon! (Selamat siang/sore)\\nHow are you? I am fine, thank you!\", \"title\": \"Friendly English Greetings\", \"highlight\": \"Good Morning, Good Afternoon, Hello & Goodbye\"}, {\"text\": \"Red is merah, Blue is biru, Yellow is kuning.\\nGreen is hijau, Pink is merah muda, and White is putih!\", \"title\": \"Colors of the Rainbow\", \"highlight\": \"Red, Blue, Yellow, Green, Pink, Purple\"}]','https://images.unsplash.com/photo-1503676260728-1c00da094a0b?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/Fe8u2I3vmHU',7,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(45,5,2,1,'Numbers 1-20, Farm Animals & Sweet Fresh Fruits','numbers-animals-and-fruits','Count one to twenty with ease, name cute animals like cat and duck, and yummy fruits like apples and bananas!','[{\"text\": \"One, two, three, four, five, six, seven, eight, nine, ten!\\nEleven, twelve, thirteen, fourteen, fifteen... up to twenty!\", \"title\": \"Counting Numbers 1 to 20\", \"highlight\": \"One (1) to Twenty (20)\"}, {\"text\": \"Cat is kucing, Dog is anjing, Bird is burung, Rabbit is kelinci.\\nApple is apel, Banana is pisang, Orange is jeruk, and Grape is anggur.\", \"title\": \"Cute Animals and Fruits\", \"highlight\": \"Cat, Rabbit, Apple, Banana, Orange\"}]','https://images.unsplash.com/photo-1534567153574-2b12153a87f0?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/Fe8u2I3vmHU',7,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(46,5,3,1,'Days of the Week, 12 Months & Telling the Time','days-months-and-telling-time','Sunday, Monday, Tuesday... learn the days of the week, calendar months, and ask \"What time is it?\" with confidence!','[{\"text\": \"Sunday (Minggu), Monday (Senin), Tuesday (Selasa), Wednesday (Rabu),\\nThursday (Kamis), Friday (Jumat), and Saturday (Sabtu).\", \"title\": \"7 Days of the Week\", \"highlight\": \"Sunday, Monday, Tuesday, Wednesday, Thursday, Friday, Saturday\"}, {\"text\": \"What time is it? (Jam berapa sekarang?)\\nIt is seven o\'clock (Sekarang jam tujuh tepat).\\nIt is half past eight (Sekarang jam setengah sembilan).\", \"title\": \"Telling Time with O\'clock\", \"highlight\": \"O\'clock (Tepat) & Half past (Lewat 30 Menit)\"}]','https://images.unsplash.com/photo-1509228468518-180dd4864904?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/Fe8u2I3vmHU',8,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(47,5,4,1,'Things in Classroom, Family Tree & Prepositions','classroom-family-and-prepositions','Look inside your school bag, introduce your lovely family members, and master position words: in, on, under, behind!','[{\"text\": \"Book (buku), Pencil (pensil), Eraser (penghapus), Ruler (penggaris),\\nDesk (meja), Chair (kursi), and Whiteboard (papan tulis putih).\", \"title\": \"Things in the Classroom\", \"highlight\": \"Pencil, Book, Bag, Ruler, Eraser\"}, {\"text\": \"The apple is ON the table (Apel di atas meja).\\nThe book is IN the bag (Buku di dalam tas).\\nThe cat is UNDER the chair (Kucing di bawah kursi).\", \"title\": \"Prepositions of Place (In, On, Under)\", \"highlight\": \"In (Di dalam), On (Di atas), Under (Di bawah)\"}]','https://images.unsplash.com/photo-1580582932707-520aed937b7b?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/Fe8u2I3vmHU',9,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(48,5,5,1,'My Daily Routine & Exploring Inspiring Professions','daily-routine-and-professions','Describe your day using Simple Present Tense, and explore future dream jobs: doctor, pilot, scientist, and teacher!','[{\"text\": \"I wake up at six o\'clock every morning.\\nI take a bath, brush my teeth, have breakfast, and go to school by bicycle.\", \"title\": \"My Cheerful Daily Routine\", \"highlight\": \"Wake up, Take a bath, Have breakfast, Go to school\"}, {\"text\": \"A doctor heals sick patients in the hospital.\\nA teacher educates smart students at school.\\nA pilot flies airplanes across the world sky!\", \"title\": \"What Do You Want to Be?\", \"highlight\": \"Doctor, Teacher, Pilot, Firefighter, Scientist\"}]','https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/Fe8u2I3vmHU',10,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(49,5,6,1,'Asking for Directions, Feelings & Simple Past Tense','directions-feelings-and-past-tense','How to ask where the bookstore is (turn left/right), describe happy emotions, and tell past stories using regular verbs!','[{\"text\": \"Excuse me, where is the library?\\nGo straight, and then turn left! It is next to the science laboratory.\", \"title\": \"Giving and Asking for Directions\", \"highlight\": \"Turn left (Belok kiri), Turn right (Belok kanan), Go straight (Lurus)\"}, {\"text\": \"Yesterday, I played football with my best friends.\\nLast Sunday, we visited our grandparents in the green countryside.\", \"title\": \"Simple Past Tense (Telling Past Events)\", \"highlight\": \"Play -> Played, Visit -> Visited, Watch -> Watched\"}]','https://images.unsplash.com/photo-1524661135-423995f22d0b?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/Fe8u2I3vmHU',10,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(50,6,1,1,'Mengenal Warna Primer & Seni Melipat Origami','warna-primer-dan-seni-origami','Tiga warna pokok: merah, kuning, biru dapat melahirkan warna baru! Dan serunya melipat kertas origami menjadi burung terbang.','[{\"text\": \"Warna primer adalah warna dasar: Merah, Kuning, dan Biru.\\nMerah dicampur Kuning menghasilkan warna Oranye.\\nKuning dicampur Biru menghasilkan warna Hijau segar!\", \"title\": \"Tiga Warna Primer yang Ajaib\", \"highlight\": \"Merah + Kuning = Oranye, Kuning + Biru = Hijau\"}, {\"text\": \"Origami adalah seni melipat kertas indah dari Jepang.\\nDengan mengikuti lipatan garis diagonal, kita bisa membuat katak loncat dan perahu layar!\", \"title\": \"Seni Melipat Kertas Origami\", \"highlight\": \"Origami Melatih Ketelitian dan Kreativitas Tangan\"}]','https://images.unsplash.com/photo-1513542789411-b6a5d4f31634?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/ocWgSgMGxKA',8,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(51,6,2,1,'Panjang Pendek Nada Ketukan & Gerak Tari Alam','panjang-pendek-nada-dan-tari-alam','Menyanyikan lagu anak dengan birama 2/4 dan 3/4, serta menirukan gerakan ranting pohon dan kupu-kupu menari.','[{\"text\": \"Nada adalah bunyi yang beraturan.\\nNada panjang dibunyikan lebih lama, sedangkan nada pendek dibunyikan sekejap mengikuti ketukan birama lagu.\", \"title\": \"Panjang dan Pendek Nada Musik\", \"highlight\": \"Ketukan Musik Membuat Lagu Terdengar Harmonis\"}, {\"text\": \"Melambaikan kedua tangan ke atas menirukan dahan pohon tertiup angin sepoi.\\nMengayunkan tangan perlahan menirukan kepakan sayap kupu-kupu di taman bunga.\", \"title\": \"Gerak Tari Menirukan Alam\", \"highlight\": \"Menari Melatih Kelenturan Tubuh yang Gemulai\"}]','https://images.unsplash.com/photo-1516450360452-9312f5e86fc7?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/ocWgSgMGxKA',8,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(52,6,3,1,'Gambar Dekoratif & Karya Kolase/Mozaik Alami','gambar-dekoratif-dan-karya-kolase','Menghias gambar hewan dengan motif batik dekoratif dan menempelkan biji jagung serta daun kering menjadi karya kolase indah.','[{\"text\": \"Gambar dekoratif adalah gambar hiasan berpola garis, lingkaran, dan motif alam tanpa meninggalkan bentuk aslinya.\", \"title\": \"Seni Gambar Dekoratif\", \"highlight\": \"Gambar Dekoratif Indah Dipandang Mata\"}, {\"text\": \"Kolase dibuat dengan menempelkan potongan bahan alam (biji-bijian, daun kering, cangkang telur) ke atas pola gambar.\\nMozaik dibuat dari potongan kertas origami berwarna-warni.\", \"title\": \"Karya Seni Kolase dan Mozaik\", \"highlight\": \"Menempel Bahan Alami dengan Lem Rapi\"}]','https://images.unsplash.com/photo-1460661419201-fd4cecdf8a8b?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/ocWgSgMGxKA',9,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(53,6,4,1,'Tempo Lagu Anak & Ragam Alat Musik Tradisional','tempo-lagu-dan-alat-musik-tradisional','Mengenal tempo cepat (allegro), sedang (moderato), dan lambat (andante), serta alunan merdu angklung dan gamelan.','[{\"text\": \"Tempo adalah cepat lambatnya suatu lagu dinyanyikan.\\nLagu bertema ceria biasanya bertempo cepat, sedangkan lagu nina bobo bertempo lambat dan tenang.\", \"title\": \"Macam-Macam Tempo Musik\", \"highlight\": \"Tempo Allegro (Cepat), Moderato (Sedang), Andante (Lambat)\"}, {\"text\": \"Angklung dari Jawa Barat dimainkan dengan cara digoyangkan.\\nGamelan dari Jawa dimainkan dengan dipukul.\\nSasando dari NTT dimainkan dengan dipetik indah.\", \"title\": \"Alat Musik Tradisional Nusantara\", \"highlight\": \"Angklung (Digoyang), Gamelan (Dipukul), Sasando (Dipetik)\"}]','https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/ocWgSgMGxKA',9,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(54,6,5,1,'Gambar Ilustrasi, Komik Ceria & Cerita Bergambar','gambar-ilustrasi-dan-komik','Membuat karakter kartun yang ekspresif, balon dialog kata, dan alur panel komik yang seru untuk dibaca kawan!','[{\"text\": \"Gambar ilustrasi berfungsi memperjelas isi cerita atau naskah buku.\\nKomik adalah gambar berurutan yang membentuk alur cerita lengkap dengan balon kata dialog tokoh.\", \"title\": \"Unsur Gambar Cerita (Ilustrasi)\", \"highlight\": \"Panel Gambar + Balon Kata = Komik Seru\"}, {\"text\": \"Pewarnaan kering menggunakan pensil warna dan krayon tanpa air.\\nPewarnaan basah menggunakan cat air dan kuas di atas kertas gambar tebal.\", \"title\": \"Teknik Pewarnaan Kering dan Basah\", \"highlight\": \"Krayon & Pensil Warna (Kering) vs Cat Air (Basah)\"}]','https://images.unsplash.com/photo-1513542789411-b6a5d4f31634?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/ocWgSgMGxKA',10,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(55,6,6,1,'Tangga Nada Diatonis Mayor-Minor & Seni Patung 3D','tangga-nada-dan-seni-patung','Ciri khas lagu bertangga nada mayor yang bersemangat dan minor yang syahdu, serta teknik membentuk patung tiga dimensi.','[{\"text\": \"Tangga nada mayor berjarak 1 - 1 - 1/2 - 1 - 1 - 1 - 1/2, bernada riang gembira dan bersemangat (contoh: Halo-Halo Bandung).\\nTangga nada minor bernada syahdu dan sedih (contoh: Gugur Bunga).\", \"title\": \"Tangga Nada Diatonis Mayor dan Minor\", \"highlight\": \"Mayor (Bersemangat) vs Minor (Khidmat/Syahdu)\"}, {\"text\": \"Karya seni 3 dimensi memiliki panjang, lebar, dan ruang volume yang dapat dilihat dari berbagai arah.\\nBahan lunak seperti plastisin dan tanah liat dibentuk memakai teknik membutsir.\", \"title\": \"Seni Patung Tiga Dimensi (3D)\", \"highlight\": \"Memiliki Panjang, Lebar, dan Ruang Volume\"}]','https://images.unsplash.com/photo-1569172122301-bc500f309134?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/ocWgSgMGxKA',11,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(56,7,1,1,'Gerak Dasar Lokomotor, Non-Lokomotor & Manipulatif','gerak-dasar-lokomotor-nonlokomotor','Berlari lincah (lokomotor), memutar badan di tempat (non-lokomotor), dan melempar-menangkap bola kasti (manipulatif)!','[{\"text\": \"Gerak lokomotor adalah gerakan yang berpindah tempat dari satu titik ke titik lain.\\nContohnya: berjalan santai, berlari cepat, dan melompat rintangan.\", \"title\": \"Gerak Lokomotor (Berpindah Tempat)\", \"highlight\": \"Lokomotor = Berpindah Tempat (Lari, Lompat, Jalan)\"}, {\"text\": \"Gerak non-lokomotor dilakukan di tempat: menekuk lutut dan memutar pinggang.\\nGerak manipulatif melibatkan benda: melempar dan menangkap bola kasti.\", \"title\": \"Gerak Non-Lokomotor & Manipulatif\", \"highlight\": \"Non-Lokomotor (Di Tempat) & Manipulatif (Memakai Benda/Bola)\"}]','https://images.unsplash.com/photo-1461896836934-ffe607ba8211?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/g3yW7B0bZ_Y',7,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(57,7,2,1,'Senam Irama Ceria & Kebiasaan 6 Langkah Cuci Tangan','senam-irama-dan-kebersihan-tubuh','Melangkah dan mengayun tangan berirama musik riang, serta mempraktikkan cara mencuci tangan dengan sabun yang higienis.','[{\"text\": \"Senam irama menggabungkan gerakan langkah kaki dan ayunan lengan mengikuti irama ketukan musik.\\nSenam membuat jantung sehat dan otot tubuh menjadi lentur.\", \"title\": \"Senam Irama Penuh Semangat\", \"highlight\": \"Gerak Tubuh Selaras Irama Musik\"}, {\"text\": \"Gunakan air mengalir dan sabun busa.\\nGosok telapak, punggung tangan, sela-sela jari, ujung kuku, dan ibu jari selama 20 detik agar kuman kabur!\", \"title\": \"6 Langkah Mencuci Tangan Bersih\", \"highlight\": \"Cuci Tangan Memakai Sabun dan Air Mengalir\"}]','https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/g3yW7B0bZ_Y',7,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(58,7,3,1,'Permainan Gobak Sodor & Latihan Kelincahan Kaki','gobak-sodor-dan-kelincahan-kaki','Serunya permainan tradisional gobak sodor untuk melatih kelincahan gerak, kecepatan lari, dan kekompakan tim regu!','[{\"text\": \"Permainan beregu yang dimainkan di lapangan bergaris petak.\\nSatu regu berjaga di garis batas, regu penyerang berusaha melewati garis tanpa tersentuh tangan penjaga.\", \"title\": \"Aturan Permainan Gobak Sodor\", \"highlight\": \"Melatih Kerja Sama Tim dan Kecepatan Berlari\"}, {\"text\": \"Lari zig-zag melewati corong melatih kaki agar lincah berbelok tanpa terjatuh.\\nMinum air putih secukupnya setelah berolahraga agar tubuh tidak lemas.\", \"title\": \"Latihan Kelincahan dan Kebugaran\", \"highlight\": \"Lari Zig-Zag Melatih Refleks dan Kelincahan\"}]','https://images.unsplash.com/photo-1461896836934-ffe607ba8211?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/g3yW7B0bZ_Y',8,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(59,7,4,1,'Teknik Dasar Bola Besar: Sepak Bola & Bola Voli','teknik-sepakbola-dan-bolavoli','Mengoper bola dengan kaki bagian dalam, passing bawah bola voli yang stabil, serta menjunjung tinggi sportivitas di lapangan!','[{\"text\": \"Gunakan kaki bagian dalam untuk mengoper bola mendatar ke kaki rekan setim.\\nPosisikan badan seimbang dan pandangan tertuju ke arah sasaran operan.\", \"title\": \"Teknik Mengoper Sepak Bola (Passing)\", \"highlight\": \"Passing Kaki Bagian Dalam = Operan Akurat\"}, {\"text\": \"Rapatkan kedua tangan dan luruskan siku saat menyambut bola voli yang melambung.\\nKalah atau menang tetap bersalaman dan saling menghormati lawan.\", \"title\": \"Passing Bawah Bola Voli & Sportivitas\", \"highlight\": \"Sportivitas = Saling Menghormati dan Jujur\"}]','https://images.unsplash.com/photo-1579952363873-27f3bade9f55?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/g3yW7B0bZ_Y',9,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(60,7,5,1,'Senam Lantai Guling Depan, Renang Dasar & P3K','senam-lantai-renang-dan-p3k','Cara aman berguling ke depan di matras, meluncur di kolam renang, dan mengobati luka lecet memakai obat antiseptik.','[{\"text\": \"Lakukan pemanasan terlebih dahulu.\\nTumpukan telapak tangan di matras, tekuk dagu menempel ke dada, dan gulingkan badan dengan lembut.\", \"title\": \"Teknik Aman Guling Depan (Forward Roll)\", \"highlight\": \"Dagu Menempel Dada Menjaga Leher Tetap Aman\"}, {\"text\": \"Jangan berlari di tepi kolam karena licin.\\nJika lutut tergores lecet, bersihkan dengan air mengalir lalu oleskan cairan antiseptik dari kotak P3K.\", \"title\": \"Keselamatan di Kolam & Kotak P3K\", \"highlight\": \"P3K = Pertolongan Pertama Pada Kecelakaan\"}]','https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/g3yW7B0bZ_Y',10,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(61,7,6,1,'Latihan Daya Tahan Jantung & Menolak Bahaya Rokok','daya-tahan-jantung-dan-bahaya-rokok','Meningkatkan kapasitas paru-paru dengan jogging santai, push-up anak, serta komitmen kuat menjauhi asap rokok dan NAPZA.','[{\"text\": \"Lari pelan (jogging) selama 15 menit memperkuat otot jantung memompa darah segar.\\nLatihan push-up dan sit-up memperkuat otot lengan dan perut kita.\", \"title\": \"Latihan Daya Tahan Jantung dan Paru\", \"highlight\": \"Kebugaran Jasmani Menangkal Berbagai Penyakit\"}, {\"text\": \"Rokok mengandung zat racun nikotin dan tar yang merusak paru-paru dan jantung.\\nJadilah anak cerdas yang berani menolak ajakan merokok demi masa depan gemilang!\", \"title\": \"Katakan Tidak pada Asap Rokok & NAPZA!\", \"highlight\": \"Paru-Paru Bersih, Hidup Sehat dan Berprestasi\"}]','https://images.unsplash.com/photo-1461896836934-ffe607ba8211?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/g3yW7B0bZ_Y',10,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(62,8,1,1,'Mengenal Tuhan Yang Maha Esa & Mensyukuri Ciptaan-Nya','mengenal-tuhan-dan-mensyukuri-ciptaan','Tuhan menciptakan matahari hangat, pepohonan rindang, dan tubuh kita yang sehat. Mari bersyukur setiap hari!','[{\"text\": \"Langit biru, bintang berkelap-kelip, dan lautan luas adalah ciptaan Tuhan Yang Maha Esa.\\nTuhan Maha Pengasih dan Maha Penyayang kepada semua makhluk.\", \"title\": \"Tuhan Maha Pencipta Alam Semesta\", \"highlight\": \"Tuhan Maha Pencipta Seluruh Alam Semesta\"}, {\"text\": \"Bersyukur dilakukan dengan merawat tanaman, tidak menyakiti binatang, serta menjaga kesehatan tubuh anugerah Tuhan.\", \"title\": \"Wujud Syukur dalam Keseharian\", \"highlight\": \"Menyayangi Alam Adalah Wujud Syukur\"}]','https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/Fe8u2I3vmHU',7,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(63,8,2,1,'Tata Cara Ibadah Wajib & Doa Harian Anak Beriman','tata-cara-ibadah-dan-doa-harian','Berdoa sebelum makan, doa sebelum tidur, serta mengenal 6 tempat ibadah yang tenang dan suci di nusantara.','[{\"text\": \"Awali makan minum dengan doa syukur agar berkah.\\nBerdoalah sebelum tidur di malam hari agar dilindungi dan bangun dengan ceria.\", \"title\": \"Membiasakan Berdoa Sehari-hari\", \"highlight\": \"Doa Menenangkan Hati dan Membawa Kebaikan\"}, {\"text\": \"Masjid untuk umat Islam, Gereja untuk umat Kristen dan Katolik,\\nPura untuk umat Hindu, Vihara untuk umat Buddha, dan Klenteng untuk umat Khonghucu.\", \"title\": \"Mengenal Rumah Ibadah di Indonesia\", \"highlight\": \"Menghormati Seluruh Rumah Ibadah Sahabat Kita\"}]','https://images.unsplash.com/photo-1548625361-19597c55cb52?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/Fe8u2I3vmHU',8,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(64,8,3,1,'Akhlak Mulia: Kejujuran & Menghormati Orang Tua','akhlak-mulia-dan-kejujuran','Indahnya berbicara jujur, tidak mengambil milik orang lain, serta patuh dan berbakti kepada ayah-ibu dan bapak-ibu guru.','[{\"text\": \"Anak yang jujur selalu mengatakan yang sebenarnya tanpa berbohong.\\nOrang jujur dicintai Tuhan dan dipercaya oleh semua sahabatnya.\", \"title\": \"Kejujuran Membawa Ketenangan Hati\", \"highlight\": \"Jujur Adalah Mahkota Perilaku Terpuji\"}, {\"text\": \"Bicara dengan suara lembut kepada ayah dan ibu.\\nMendengarkan nasehat guru dengan patuh dan mendoakan kebaikan bagi mereka.\", \"title\": \"Hormat dan Patuh kepada Orang Tua & Guru\", \"highlight\": \"Berbakti Kepada Orang Tua dan Menghormati Guru\"}]','https://images.unsplash.com/photo-1511895426328-dc8714191300?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/Fe8u2I3vmHU',8,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(65,8,4,1,'Kisah Teladan Tokoh Suci Penuh Kasih Sayang & Toleransi','kisah-teladan-dan-toleransi','Meneladani sifat sabar para nabi, rasul, dan tokoh suci yang dermawan, rendah hati, dan cinta damai.','[{\"text\": \"Tokoh suci tidak pernah membalas kejahatan dengan kejahatan, melainkan dengan senyuman dan doa kebaikan.\\nSifat pemaaf dan dermawan membuat hati damai sentosa.\", \"title\": \"Keteladanan Sifat Sabar dan Pemaaf\", \"highlight\": \"Membalas Keburukan dengan Kebaikan yang Tulus\"}, {\"text\": \"Tidak mengganggu sahabat yang sedang beribadah sesuai keyakinannya.\\nSaling berbagi kebahagiaan dan tolong-menolong saat tetangga ditimpa musibah.\", \"title\": \"Sikap Toleransi Antarumat Beragama\", \"highlight\": \"Toleransi Menjaga Perdamaian dan Kasih Sayang\"}]','https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800&auto=format&fit=crop&q=80','https://www.youtube.com/embed/Fe8u2I3vmHU',9,'2026-10-07 08:47:50','2026-10-07 08:47:50');
/*!40000 ALTER TABLE `lessons` ENABLE KEYS */;
