INSERT INTO `quizzes` VALUES (1,1,'Indra tubuh manakah yang kita gunakan untuk melihat warna-warni pelangi di langit?','Telinga','Mata','Hidung','Lidah','B','Tepat sekali! 🎉 Mata yang jernih digunakan untuk melihat pemandangan indah di sekitar kita.',10,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(2,1,'Saat ibu memanggang kue bolu, kita mencium aroma harumnya menggunakan...','Hidung','Kulit','Lidah','Mata','A','Hebat! 👃 Hidung berfungsi sebagai indra pembau untuk mencium wangi aroma masakan lezat.',10,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(3,2,'Manakah di bawah ini yang termasuk contoh makhluk hidup?','Mobil mainan','Kucing anggora','Pensil gambar','Batu kali','B','Benar sekali! 🐱 Kucing adalah makhluk hidup karena bernapas, makan, dan bisa tumbuh besar.',10,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(4,2,'Salah satu ciri utama makhluk hidup yang membedakannya dari benda mati adalah...','Bisa bertambah berat dan bertumbuh','Tidak membutuhkan makan dan minum','Tidak bisa bernapas','Terbuat dari bahan plastik','A','Pintar! 🌱 Makhluk hidup membutuhkan makanan untuk bertumbuh dan berkembang biak.',10,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(5,3,'Orang tua dari ayah dan ibu kita biasa kita panggil dengan sebutan...','Paman dan bibi','Kakek dan nenek','Kakak dan adik','Sepupu','B','Tepat sekali! 👴👵 Kakek dan nenek adalah orang tua dari ayah dan ibu kita tercinta.',10,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(6,3,'Sikap yang baik saat melihat ibu sedang sibuk merapikan rumah adalah...','Membantu menyapu lantai dengan gembira','Mengotori lantai dengan mainan','Tidur-tiduran tanpa peduli','Menangis meminta jajan','A','Luar biasa! 🧹 Anak berbakti selalu senang meringankan beban pekerjaan orang tua di rumah.',10,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(7,4,'Urutan siklus metamorfosis kupu-kupu yang benar sejak awal adalah...','Telur -> Ulat -> Kepompong -> Kupu-kupu','Kepompong -> Telur -> Kupu-kupu -> Ulat','Ulat -> Telur -> Kepompong -> Kupu-kupu','Kupu-kupu -> Kepompong -> Telur -> Ulat','A','Keren banget! 🦋 Dimulai dari telur di daun, menetas jadi ulat, tidur dalam kepompong, lalu jadi kupu-kupu cantik!',10,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(8,4,'Pada fase apakah calon kupu-kupu beristirahat membungkus diri selama berhari-hari?','Fase telur','Fase larva','Fase kepompong (pupa)','Fase imago dewasa','C','Tepat! 🌿 Kepompong (pupa) adalah fase ajaib di mana ulat berubah menjadi bersayap warna-warni.',10,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(9,5,'Zat warna hijau pada daun yang bertugas menyerap sinar matahari disebut...','Oksigen','Klorofil','Karbohidrat','Mineral','B','Cerdas! 🍃 Klorofil adalah zat hijau daun yang membantu tumbuhan memasak makanannya.',10,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(10,5,'Gas penting apakah yang dihasilkan oleh tumbuhan saat fotosintesis untuk kita hirup?','Oksigen (O2)','Karbondioksida','Asap knalpot','Nitrogen cair','A','Benar sekali! 💨 Oksigen yang segar membuat udara bumi sejuk dan sehat dihirup.',10,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(11,6,'Peristiwa perubahan wujud benda padat menjadi cair (seperti es batu terkena panas) disebut...','Membeku','Mencair','Mengembun','Menyublim','B','Tepat! 🧊 Es batu yang menyerap panas akan mencair menjadi air jernih.',10,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(12,6,'Titik-titik air yang muncul di daun pada pagi hari merupakan contoh peristiwa...','Mengembun','Menguap','Mencair','Membeku','A','Bagus sekali! 💧 Uap air di udara dingin berubah menjadi butiran air embun segar.',10,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(13,7,'Gaya apakah yang kita gunakan saat menendang bola sepak menuju gawang?','Gaya magnet','Gaya gravitasi','Gaya otot kaki','Gaya pegas','C','Mantap! ⚽ Otot kaki kita mengeluarkan gaya dorong untuk melayangkan bola.',10,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(14,7,'Kipas angin yang berputar kencang mengubah energi listrik menjadi energi...','Gerak','Bunyi','Kimia','Cahaya','A','Hebat! 🌀 Baling-baling kipas berputar menghasilkan hembusan angin sejuk dari energi gerak.',10,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(15,8,'Jika kita berdiri menghadap arah matahari terbit (Timur), maka punggung kita menghadap arah...','Utara','Selatan','Barat','Tenggara','C','Benar! 🧭 Matahari terbit di Timur dan tenggelam di Barat, sehingga arah belakang kita adalah Barat.',10,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(16,8,'Manakah di bawah ini yang merupakan contoh lingkungan buatan manusia?','Gunung Merapi','Danau Toba','Waduk Jatiluhur','Hutan belantara','C','Tepat! 🏗️ Waduk dibuat manusia untuk menampung air dan pembangkit listrik.',10,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(17,9,'Organ pencernaan yang bertugas menghaluskan makanan dengan bantuan asam lambung adalah...','Mulut','Lambung','Kerongkongan','Usus besar','B','Benar sekali! 🥣 Lambung meremas dan melumatkan makanan sebelum nutrisinya diserap usus.',10,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(18,9,'Pertukaran gas oksigen dan karbondioksida di paru-paru berlangsung di dalam...','Alveolus','Tenggorokan','Bronkus','Hidung','A','Pintar! 🫁 Gelembung halus alveolus adalah tempat pertukaran udara bersih oksigen ke darah.',10,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(19,10,'Dalam rantai makanan di sawah: Padi -> Belalang -> Katak -> Ular, yang bertindak sebagai produsen adalah...','Belalang','Katak','Padi','Ular','C','Keren! 🌾 Padi adalah produsen karena mampu memproduksi makanan sendiri melalui fotosintesis.',10,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(20,10,'Peran jamur dan bakteri dalam rantai makanan adalah sebagai...','Konsumen puncak','Pengurai (dekomposer)','Produsen primer','Pemangsa hama','B','Luar biasa! 🍄 Pengurai menguraikan bangkai makhluk hidup menjadi zat hara penyubur tanah.',10,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(21,11,'Planet terbesar dalam tata surya kita yang memiliki gravitasi sangat kuat adalah...','Mars','Jupiter','Bumi','Venus','B','Tepat sekali! 🪐 Jupiter adalah planet raksasa terbesar di tata surya kita.',10,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(22,11,'Perputaran bumi pada porosnya (rotasi bumi) selama 24 jam mengakibatkan terjadinya...','Pergantian siang dan malam','Pergantian musim kemarau dan hujan','Gerhana matahari total','Pasang surut air laut tahunan','A','Cerdas! 🌍 Rotasi bumi membuat belahan bumi bergantian menghadap dan membelakangi matahari.',10,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(23,12,'Pensil yang dimasukkan ke dalam gelas berisi air tampak patah. Hal ini membuktikan sifat cahaya dapat...','Dibiaskan (dibelokkan)','Merambat lurus tanpa belok','Menembus benda gelap pekat','Dipantulkan seluruhnya','A','Hebat! ✏️ Pembiasan terjadi saat berkas cahaya melewati medium udara ke air yang berbeda kerapatannya.',10,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(24,12,'Semua bunyi yang merambat sampai ke telinga kita pada dasarnya dihasilkan dari benda yang...','Bergetar','Diam membeku','Menyerap panas','Menguap','A','Mantap! 🔊 Getaran senar atau membran drum menggetarkan udara hingga sampai ke telinga kita.',10,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(25,13,'Teks Proklamasi Kemerdekaan Republik Indonesia dibacakan pada tanggal...','17 Agustus 1945','28 Oktober 1928','1 Juni 1945','20 Mei 1908','A','Merdeka! 🇮🇩 17 Agustus 1945 adalah hari bersejarah proklamasi kemerdekaan bangsa Indonesia.',10,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(26,13,'Negara Indonesia terletak di antara dua samudra luas di dunia, yaitu...','Samudra Hindia dan Samudra Pasifik','Samudra Atlantik dan Artik','Samudra Hindia dan Atlantik','Laut Mediterania dan Baltik','A','Benar! 🌊 Posisi silang strategis ini membuat Indonesia kaya akan potensi kelautan maritim.',10,'2026-10-07 08:47:50','2026-10-07 08:47:50'),(27,14,'Manakah perbandingan angka di bawah ini yang paling tepat?','45 lebih sedikit daripada 20','78 lebih banyak daripada 52','30 lebih banyak daripada 60','15 sama dengan 50','B','Tepat sekali! 🌟 Angka 