/*!40000 ALTER TABLE `subjects` DISABLE KEYS */;
INSERT INTO `subjects` VALUES (1,'IPAS (Sains & Sosial)','ipas',NULL,'Atom','#3B82F6','Ayo jelajahi panca indra, daur hidup hewan, wujud benda, fotosintesis, tata surya, dan sejarah sosial nusantara!','2026-10-07 08:47:50','2026-10-07 08:47:50'),(2,'Matematika (Numerasi & Logika)','matematika',NULL,'Calculator','#10B981','Belajar berhitung seru, bilangan cacah, perkalian bersusun, pecahan senilai, geometri, dan logika angka!','2026-10-07 08:47:50','2026-10-07 08:47:50'),(3,'Bahasa Indonesia (Literasi & Sastra)','bahasa-indonesia',NULL,'BookOpen','#F59E0B','Membaca dongeng fabel, kalimat santun, ide pokok paragraf, puisi anak, pantun nasehat, dan teks eksplanasi.','2026-10-07 08:47:50','2026-10-07 08:47:50'),(4,'Pendidikan Pancasila / PKn','pancasila',NULL,'ShieldCheck','#EF4444','Makna simbol Garuda Pancasila, aturan di rumah & sekolah, hak dan kewajiban anak, serta persatuan NKRI.','2026-10-07 08:47:50','2026-10-07 08:47:50'),(5,'Bahasa Inggris (English for Kids)','bahasa-inggris',NULL,'Languages','#06B6D4','Learn alphabet, cheerful colors, animals, telling time, prepositions, professions, and daily conversations!','2026-10-07 08:47:50','2026-10-07 08:47:50'),(6,'SBdP (Seni Budaya & Prakarya)','sbdp',NULL,'Palette','#EC4899','Berekspresi lewat warna primer, karya kolase bahan alam, origami kreatif, tempo musik, dan komik bergambar.','2026-10-07 08:47:50','2026-10-07 08:47:50'),(7,'PJOK (Pendidikan Jasmani & Kesehatan)','pjok',NULL,'HeartPulse','#8B5CF6','Gerak lokomotor ceria, senam irama, permainan bola, senam lantai, dan budaya hidup bersih sehat.','2026-10-07 08:47:50','2026-10-07 08:47:50'),(8,'Pendidikan Agama & Budi Pekerti','pendidikan-agama',NULL,'Sparkles','#14B8A6','Mengenal keagungan Tuhan, doa harian, adab sopan santun kepada orang tua & guru, serta kisah teladan mulia.','2026-10-07 08:47:50','2026-10-07 08:47:50');
/*!40000 ALTER TABLE `subjects` ENABLE KEYS */;
UNLOCK TABLES;

